export function collectScreens(nodes) {
  const screens = [];
  for (const node of nodes) {
    if (node.enabled === false) continue;
    if (node.screen) screens.push(node.screen);
    screens.push(...collectScreens(node.children ?? []));
  }
  return screens;
}

